$ErrorActionPreference='Stop';$root=Split-Path $PSScriptRoot -Parent;Import-Module (Join-Path $root 'Apps\Calculator.ObjectImageV2.psm1') -Force;$p=Join-Path $root 'Conformance\Calculator.ps1';$calculator=New-Module -AsCustomObject -ArgumentList $p {param($path);$env:DP_SKIP_START='1';. $path;$script:s=[CalculatorState]::new();function Get-CalculatorSemanticRoots{[pscustomobject]@{State=$script:s;Buttons=$script:Buttons}};Export-ModuleMember -Function Get-CalculatorSemanticRoots,Invoke-CalculatorLogic};$image=Export-CalculatorObjectImageV2 $calculator $calculator.'Get-CalculatorSemanticRoots'();$file=Join-Path $env:TEMP 'smadirect-v2.bin';[IO.File]::WriteAllBytes($file,$image.Bytes);$exe=Join-Path $root 'Apps\ObjectReplica\CalculatorObjectImageV2Replica.exe';$id=[guid]::NewGuid().ToString('N');$r="Global\SMADirect_V2_$id";$f="Global\SMADirect_V2Fence_$id";$o=Join-Path $env:TEMP "v2-$id.txt";try{$q=Start-Process $exe -ArgumentList @('producer',$r,$f,$file) -RedirectStandardOutput $o -PassThru -WindowStyle Hidden;Start-Sleep -Milliseconds 700;$n=& $exe consumer $r $f 2>&1;$c=$LASTEXITCODE;$q.WaitForExit(7000)|Out-Null;if($c -ne 0 -or $n -notmatch 'verdict=PASS'){throw "v2 native receipt failed: $n"};[pscustomobject]@{test='Calculator ObjectImage v2 native replica';pass=$true;producer="objects=$($image.ObjectCount) members=$($image.MemberCount) opaque=$($image.HostedOpaque)";native=$n;verdict='PASS'}}finally{Remove-Item $file,$o -Force -ErrorAction SilentlyContinue}
